+import { useState } from "react";
+import { useForm } from "react-hook-form";
+import { zodResolver } from "@hookform/resolvers/zod";
+import { Button } from "@/components/ui/button";
+import { Input } from "@/components/ui/input";
+import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
+import { Form, FormControl, FormField, FormItem, FormLabel, FormMessage } from "@/components/ui/form";
+import { Lock, Shield } from "lucide-react";
+import { adminLoginSchema, type AdminLogin } from "@shared/schema";
+import { useAuth } from "@/hooks/useAuth";
+
+interface AdminLoginProps {
+  onLogin: () => void;
+}
+
+export default function AdminLogin({ onLogin }: AdminLoginProps) {
+  const [error, setError] = useState<string | null>(null);
+  const { login } = useAuth();
+
+  const form = useForm<AdminLogin>({
+    resolver: zodResolver(adminLoginSchema),
+    defaultValues: {
+      password: "",
+    },
+  });
+
+  const handleSubmit = (data: AdminLogin) => {
+    const success = login(data.password);
+    if (success) {
+      setError(null);
+      onLogin();
+    } else {
+      setError("Incorrect password. Please try again.");
+      form.reset();
+    }
+  };
+
+  return (
+    <div className="min-h-screen bg-gradient-to-br from-amber-50 to-orange-100 flex items-center justify-center p-4">
+      <Card className="w-full max-w-md">
+        <CardHeader className="text-center">
+          <div className="mx-auto mb-4 w-12 h-12 bg-amber-100 rounded-full flex items-center justify-center">
+            <Shield className="w-6 h-6 text-amber-600" />
+          </div>
+          <CardTitle className="text-2xl font-bold text-gray-900">Admin Access</CardTitle>
+          <CardDescription>Enter your password to manage Brown Feed Store</CardDescription>
+        </CardHeader>
+        <CardContent>
+          <Form {...form}>
+            <form onSubmit={form.handleSubmit(handleSubmit)} className="space-y-4">
+              <FormField
+                control={form.control}
+                name="password"
+                render={({ field }) => (
+                  <FormItem>
+                    <FormLabel>Password</FormLabel>
+                    <FormControl>
+                      <div className="relative">
+                        <Lock className="absolute left-3 top-3 h-4 w-4 text-gray-400" />
+                        <Input
+                          type="password"
+                          placeholder="Enter admin password"
+                          className="pl-10"
+                          {...field}
+                        />
+                      </div>
+                    </FormControl>
+                    <FormMessage />
+                  </FormItem>
+                )}
+              />
+              
+              {error && (
+                <div className="text-red-600 text-sm bg-red-50 p-3 rounded-md border border-red-200">
+                  {error}
+                </div>
+              )}
+              
+              <Button 
+                type="submit" 
+                className="w-full bg-amber-600 hover:bg-amber-700"
+                disabled={form.formState.isSubmitting}
+              >
+                {form.formState.isSubmitting ? "Logging in..." : "Login"}
+              </Button>
+            </form>
+          </Form>
+          
+          <div className="mt-6 text-center text-sm text-gray-500">
+            <p>Secure access to store management</p>
+          </div>
+        </CardContent>
