+import { useState, useRef } from "react";
+import { Button } from "@/components/ui/button";
+import { Input } from "@/components/ui/input";
+import { Upload, X, Image } from "lucide-react";
+import { useToast } from "@/hooks/use-toast";
+
+interface FileUploadProps {
+  onUpload: (url: string) => void;
+  currentUrl?: string;
+  label: string;
+  accept: string;
+  maxSize?: number; // in MB
+}
+
+export default function FileUpload({ onUpload, currentUrl, label, accept, maxSize = 5 }: FileUploadProps) {
+  const [uploading, setUploading] = useState(false);
+  const [preview, setPreview] = useState<string | null>(currentUrl || null);
+  const fileInputRef = useRef<HTMLInputElement>(null);
+  const { toast } = useToast();
+
+  const handleFileSelect = async (event: React.ChangeEvent<HTMLInputElement>) => {
+    const file = event.target.files?.[0];
+    if (!file) return;
+
+    // Validate file size
+    if (file.size > maxSize * 1024 * 1024) {
+      toast({
+        title: "File too large",
+        description: `Please select a file smaller than ${maxSize}MB`,
+        variant: "destructive",
+      });
+      return;
+    }
+
+    // Create preview for images
+    if (file.type.startsWith('image/')) {
+      const reader = new FileReader();
+      reader.onload = (e) => setPreview(e.target?.result as string);
+      reader.readAsDataURL(file);
+    }
+
+    // Upload file
+    setUploading(true);
+    try {
+      const formData = new FormData();
+      formData.append('file', file);
+
+      const response = await fetch('/api/upload', {
+        method: 'POST',
+        body: formData,
+      });
+
+      if (!response.ok) {
+        throw new Error('Upload failed');
+      }
+
+      const { url } = await response.json();
+      onUpload(url);
+      
+      toast({
+        title: "Upload successful",
+        description: `${label} uploaded successfully`,
+      });
+    } catch (error) {
+      toast({
+        title: "Upload failed",
+        description: "Please try again",
+        variant: "destructive",
+      });
+      setPreview(currentUrl || null);
+    } finally {
+      setUploading(false);
+    }
+  };
+
+  const handleRemove = () => {
+    setPreview(null);
+    onUpload('');
+    if (fileInputRef.current) {
+      fileInputRef.current.value = '';
+    }
+  };
+
+  return (
+    <div className="space-y-3">
+      <label className="block text-sm font-medium">{label}</label>
+      
+      {preview ? (
+        <div className="relative">
+          {accept.includes('image') ? (
+            <img 
+              src={preview} 
+              alt="Preview" 
+              className="w-32 h-32 object-cover rounded-lg border"
+            />
+          ) : (
+            <div className="w-32 h-32 bg-gray-100 rounded-lg border flex items-center justify-center">
+              <Image className="w-8 h-8 text-gray-400" />
+            </div>
+          )}
+          <Button
+            type="button"
+            variant="destructive"
+            size="sm"
+            className="absolute -top-2 -right-2 w-6 h-6 rounded-full p-0"
+            onClick={handleRemove}
+          >
+            <X className="w-3 h-3" />
+          </Button>
+        </div>
+      ) : (
+        <div className="border-2 border-dashed border-gray-300 rounded-lg p-4 text-center">
+          <Upload className="w-8 h-8 text-gray-400 mx-auto mb-2" />
+          <p className="text-sm text-gray-500 mb-2">Click to upload {label.toLowerCase()}</p>
+          <Button
+            type="button"
+            variant="outline"
+            size="sm"
+            onClick={() => fileInputRef.current?.click()}
+            disabled={uploading}
+          >
+            {uploading ? "Uploading..." : "Choose File"}
+          </Button>
+        </div>
+      )}
+
+      <Input
+        ref={fileInputRef}
+        type="file"
+        accept={accept}
+        onChange={handleFileSelect}
+        className="hidden"
+      />
+      
+      <p className="text-xs text-gray-500">
+        Max file size: {maxSize}MB. Supported formats: {accept.replace(/\./g, '').toUpperCase()}
+      </p>
+    </div>
+  );
+}
