+interface ThemeGenerationResult {
+  businessAnalysis: string;
+  themes: ThemeOption[];
+}
+
+export default function ThemeGenerator() {
+  const [generatedThemes, setGeneratedThemes] = useState<ThemeGenerationResult | null>(null);
